import test from 'node:test';import assert from 'node:assert/strict';
import {encodeAudioBuffer,decodeAudioBuffer,validateProject,projectBlob} from './project-session.js';
const buffer={length:32,sampleRate:48000,numberOfChannels:2,getChannelData:n=>Float32Array.from({length:32},(_,i)=>(i/31*2-1)*(n?-.5:.5))};
test('roundtrip PCM quantizes with bounded 16-bit accuracy',()=>{const packet=encodeAudioBuffer(buffer);assert.equal(packet.frames,32);const context={createBuffer:(channels,frames,rate)=>({sampleRate:rate,numberOfChannels:channels,length:frames,data:[new Float32Array(frames),new Float32Array(frames)],getChannelData(i){return this.data[i]}})};const out=decodeAudioBuffer(context,packet);for(let c=0;c<2;c++)for(let i=0;i<32;i++)assert.ok(Math.abs(out.getChannelData(c)[i]-buffer.getChannelData(c)[i])<1/32767)});
test('reject malformed audio metadata',()=>{const packet=encodeAudioBuffer(buffer);assert.throws(()=>decodeAudioBuffer({createBuffer(){}},{...packet,frames:999}),/truncated/);assert.throws(()=>decodeAudioBuffer({createBuffer(){}},{...packet,encoding:'unknown'}),/Invalid/)});
test('project compatibility catches absent state',()=>{assert.throws(()=>validateProject({format:'clawstudio-project',version:1}),/Invalid Drum/);const dummy={format:'clawstudio-project',version:1,drum:{state:{bank:{patterns:Array(16).fill({})},voices:Array(11).fill({})}},rack:{mono:{},poly:{},texture:{},acid:{}},sampler:{slots:Array(4).fill({})},conductor:{scenes:Array(8).fill({}),lanes:Array(4).fill({})}};assert.equal(validateProject(dummy),dummy);assert.equal(projectBlob(dummy).type,'application/json')});
